/**
 * Golden-baseline capture script for the workspace index renderers.
 *
 * Not a test: it lives under `src/tests/fixtures/`, compiles to
 * `dist/tests/fixtures/`, and is not matched by the `npm test` globs.
 *
 * Usage:
 *
 *     npm run build && node dist/tests/fixtures/capture-golden.js <target> [--check]
 *
 * Targets:
 *   baseline  Renders README.md for fixtures A, B and C
 *             (see `workspace-index-contexts.ts`) and writes it to
 *             `src/tests/fixtures/workspace-index-baseline.ts` as
 *             `BASELINE_README_A/B/C`. (The AGENTS baseline was retired:
 *             the AGENTS text changes intentionally.)
 *   postB     Renders AGENTS.md and README.md for fixtures A, B and C and
 *             their two-workspace variants (`*_TWO`) and writes them to
 *             `src/tests/fixtures/workspace-index-postB.ts` as
 *             `POSTB_AGENTS_<ctx>` / `POSTB_README_<ctx>` (ctx = A, B, C,
 *             A_TWO, B_TWO, C_TWO). A reviewed regression snapshot of the
 *             post-Phase-B output, not a correctness oracle.
 *
 * Flags:
 *   --check   Write nothing. Compare the freshly rendered output with the
 *             committed baseline constants; exit 1 and print the first
 *             differing line on any difference, exit 0 otherwise.
 *
 * The baseline file is written to the `src/` tree (resolved relative to this
 * compiled script), so run it from a built checkout.
 */

import fs from 'node:fs';
import path from 'node:path';

import { renderWorkspaceAgents, renderWorkspaceReadme } from '../../orchestration/workspace-index.js';
import {
    CONTEXT_A,
    CONTEXT_B,
    CONTEXT_C,
    CONTEXT_A_TWO,
    CONTEXT_B_TWO,
    CONTEXT_C_TWO,
} from './workspace-index-contexts.js';

const USAGE = 'Usage: node dist/tests/fixtures/capture-golden.js <baseline|postB> [--check]';

const FIXTURES = { A: CONTEXT_A, B: CONTEXT_B, C: CONTEXT_C } as const;

const FIXTURES_WITH_TWO = {
    ...FIXTURES,
    A_TWO: CONTEXT_A_TWO,
    B_TWO: CONTEXT_B_TWO,
    C_TWO: CONTEXT_C_TWO,
} as const;

interface Target {
    /** Output file name (without extension), under `src/tests/fixtures/`. */
    file: string;
    /** Constant name -> freshly rendered text, in output order. */
    render: () => Array<[string, string]>;
}

function renderBaseline(): Array<[string, string]> {
    const entries: Array<[string, string]> = [];
    for (const [key, ctx] of Object.entries(FIXTURES)) {
        entries.push([`BASELINE_README_${key}`, renderWorkspaceReadme(ctx)]);
    }
    return entries;
}

function renderPostB(): Array<[string, string]> {
    const entries: Array<[string, string]> = [];
    for (const [key, ctx] of Object.entries(FIXTURES_WITH_TWO)) {
        entries.push([`POSTB_AGENTS_${key}`, renderWorkspaceAgents(ctx)]);
    }
    for (const [key, ctx] of Object.entries(FIXTURES_WITH_TWO)) {
        entries.push([`POSTB_README_${key}`, renderWorkspaceReadme(ctx)]);
    }
    return entries;
}

const TARGETS: Record<string, Target> = {
    baseline: { file: 'workspace-index-baseline', render: renderBaseline },
    postB: { file: 'workspace-index-postB', render: renderPostB },
};

function renderSource(target: string, entries: Array<[string, string]>): string {
    const header =
        '// GENERATED by dist/tests/fixtures/capture-golden.js - do not edit by hand.\n' +
        `// Re-capture: npm run build && node dist/tests/fixtures/capture-golden.js ${target}\n\n`;
    const body = entries.map(([name, text]) => `export const ${name}: string = ${JSON.stringify(text)};\n`);
    return header + body.join('\n');
}

/** Returns a description of the first differing line, or null when equal. */
function firstDifference(expected: string, actual: string): string | null {
    if (expected === actual) {
        return null;
    }
    const e = expected.split('\n');
    const a = actual.split('\n');
    const max = Math.max(e.length, a.length);
    for (let i = 0; i < max; i++) {
        if (e[i] !== a[i]) {
            return `line ${i + 1}:\n  baseline: ${JSON.stringify(e[i] ?? '<missing>')}\n  rendered: ${JSON.stringify(a[i] ?? '<missing>')}`;
        }
    }
    return 'texts differ';
}

async function main(): Promise<number> {
    const args = process.argv.slice(2);
    const check = args.includes('--check');
    const positional = args.filter((arg) => !arg.startsWith('--'));
    const unknownFlags = args.filter((arg) => arg.startsWith('--') && arg !== '--check');

    if (!Object.hasOwn(TARGETS, positional[0] ?? '') || positional.length !== 1 || unknownFlags.length > 0) {
        console.error(USAGE);
        return 2;
    }

    const targetName = positional[0] as string;
    const target = TARGETS[targetName] as Target;
    const entries = target.render();
    const here = __dirname;
    // dist/tests/fixtures -> repository root -> src/tests/fixtures
    const baselineSource = path.resolve(here, '..', '..', '..', 'src', 'tests', 'fixtures', `${target.file}.ts`);

    if (!check) {
        fs.writeFileSync(baselineSource, renderSource(targetName, entries), 'utf8');
        console.log(`Wrote ${entries.length} ${targetName} constants to ${baselineSource}`);
        return 0;
    }

    // Compare against the compiled baseline module (what the tests import).
    const baseline = (await import(`./${target.file}.js`)) as Record<string, unknown>;
    let failed = false;
    for (const [name, text] of entries) {
        const committed = baseline[name];
        if (typeof committed !== 'string') {
            console.error(`${name}: missing from baseline`);
            failed = true;
            continue;
        }
        const diff = firstDifference(committed, text);
        if (diff !== null) {
            console.error(`${name} differs at ${diff}`);
            failed = true;
        }
    }
    if (failed) {
        return 1;
    }
    console.log(`${targetName} check passed: rendered output matches the committed constants.`);
    return 0;
}

main().then(
    (code) => {
        process.exitCode = code;
    },
    (err: unknown) => {
        console.error(err);
        process.exitCode = 1;
    },
);
